//! Scalar C++ 1.3 reference for the frozen browser streams.
use meshopt7::ffi as f;
fn main(){let a:Vec<_>=std::env::args().collect();let count:usize=a[1].parse().unwrap();let stride:usize=a[2].parse().unwrap();let src=std::fs::read(&a[4]).unwrap();let mut words=vec![0u32;(count*stride+3)/4];let code=unsafe{match a[3].as_str(){"ATTRIBUTES"=>f::meshopt_decodeVertexBuffer(words.as_mut_ptr().cast(),count,stride,src.as_ptr(),src.len()),"TRIANGLES"=>f::meshopt_decodeIndexBuffer(words.as_mut_ptr().cast(),count,stride,src.as_ptr(),src.len()),_=>f::meshopt_decodeIndexSequence(words.as_mut_ptr().cast(),count,stride,src.as_ptr(),src.len())}};assert_eq!(code,0);let bytes=unsafe{std::slice::from_raw_parts(words.as_ptr().cast::<u8>(),count*stride)};std::fs::write(&a[5],bytes).unwrap();}
